(5994068, 875328, 7889, '<td valign="top">Not much wrong with this at all, excellent capture. Really like the composition. Bumping this up :-)</td>', 'Not much wrong with this at all, excellent capture. Really like the composition. Bumping this up :-)', '2010-05-06 08:52:02.000000', NULL, 1),
(5994069, 872402, 7889, '<td valign="top">The lighting may not be to a lot of people''s taste but I think it works very well here. Bumping this up :-)</td>', 'The lighting may not be to a lot of people''s taste but I think it works very well here. Bumping this up :-)', '2010-05-06 08:52:55.000000', NULL, 1),
