(5994071, 876036, 7889, '<td valign="top">Seen a lot of these here at DPC but I never tire of them, excellent image and bumping the score up. :-)</td>', 'Seen a lot of these here at DPC but I never tire of them, excellent image and bumping the score up. :-)', '2010-05-06 08:54:30.000000', NULL, 1),
(5994072, 871046, 7889, '<td valign="top">Just a wonderful image and the right amount of lighting. Bumping up the vote on this one. :-)</td>', 'Just a wonderful image and the right amount of lighting. Bumping up the vote on this one. :-)', '2010-05-06 08:55:11.000000', NULL, 1),
(5994073, 865165, 7889, '<td valign="top">Love the processing on this shot and the dof. Going to bump this one up a notch .<br/> <br/>:-)</td>', 'Love the processing on this shot and the dof. Going to bump this one up a notch . :-)', '2010-05-06 08:55:47.000000', NULL, 1),
(5994075, 865800, 7889, '<td valign="top">Wow! Unusual combination but it works well here. My second pass at images in this challenge so I am bumping this up a notch. :-)</td>', 'Wow! Unusual combination but it works well here. My second pass at images in this challenge so I am bumping this up a notch. :-)', '2010-05-06 08:56:46.000000', NULL, 1),
(5994077, 871873, 7889, '<td valign="top">Wonderful image that says so much.</td>', 'Wonderful image that says so much.', '2010-05-06 08:57:38.000000', NULL, 1),
