INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5997389, 868165, 33352, '<td valign="top">Congratulations on your personal best, and such a good photo.</td>', 'Congratulations on your personal best, and such a good photo.', '2010-05-08 15:31:49.000000', NULL, 0),
(5997393, 875838, 30982, '<td valign="top">Your patience and planning paid off - this is magnificent.  Congratulations on achieving the goal you set out to achieve!  (And that''s the photograph, not the ribbon.  The ribbon is just a little icing on the cake.)</td>', 'Your patience and planning paid off - this is magnificent.  Congratulations on achieving the goal you set out to achieve!  (And that''s the photograph, not the ribbon.  The ribbon is just a little icing on the cake.)', '2010-05-08 15:32:16.000000', NULL, 0),
(5997395, 872056, 30982, '<td valign="top">I think you did well with your little camera!  The best part is the composition - that to me is very strong.  I like the bird all the way down at the bottom like that, with all that lovely orange-green bokeh/background above.</td>', 'I think you did well with your little camera!  The best part is the composition - that to me is very strong.  I like the bird all the way down at the bottom like that, with all that lovely orange-green bokeh/background above.', '2010-05-08 15:35:02.000000', NULL, 0),
(5997398, 875930, 30982, '<td valign="top">I like how the feet haven''t quite cleared for takeoff yet.  Good job with the exposure!</td>', 'I like how the feet haven''t quite cleared for takeoff yet.  Good job with the exposure!', '2010-05-08 15:37:52.000000', NULL, 0),
(5997404, 875838, 76335, '<td valign="top">Out of this world...</td>', 'Out of this world...', '2010-05-08 15:46:11.000000', NULL, 0),
