(6961489, 864857, 136989, '<td valign="top">Quite beautiful.  Ordinary town/businesses turned into art. The textures are beautiful and the use of shadows adds mystery.</td>', 'Quite beautiful.  Ordinary town/businesses turned into art. The textures are beautiful and the use of shadows adds mystery.', '2013-01-20 16:37:57.000000', NULL, 0),
(6961860, 864857, 12611, '<td valign="top">I think this is a great use of HDR. I really like the abandoned feel of a town square with the lighting very low key. I think that''s what keeps away from a traditional HDR shot, and people should have appreciated more for this reason.</td>', 'I think this is a great use of HDR. I really like the abandoned feel of a town square with the lighting very low key. I think that''s what keeps away from a traditional HDR shot, and people should have appreciated more for this reason.', '2013-01-21 08:57:16.000000', NULL, 0),
